import { useEffect, useRef, useState, useCallback } from 'react';
import { X } from 'lucide-react';

/**
 * Renders an imported article fragment and gives its figures a click-to-zoom
 * lightbox. The HTML comes from our own content pack at build time, so it is
 * trusted markup, not user input.
 */
export default function ArticleBody({ html }) {
  const ref = useRef(null);
  const [zoomed, setZoomed] = useState(null);

  const close = useCallback(() => setZoomed(null), []);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const onClick = (e) => {
      const img = e.target.closest('figure img');
      if (!img) return;
      e.preventDefault();
      setZoomed({ src: img.currentSrc || img.src, alt: img.alt, caption: img.closest('figure')?.querySelector('figcaption')?.textContent || '' });
    };
    el.addEventListener('click', onClick);
    return () => el.removeEventListener('click', onClick);
  }, [html]);

  useEffect(() => {
    if (!zoomed) return;
    const onKey = (e) => { if (e.key === 'Escape') close(); };
    document.addEventListener('keydown', onKey);
    document.documentElement.style.overflow = 'hidden';
    return () => {
      document.removeEventListener('keydown', onKey);
      document.documentElement.style.overflow = '';
    };
  }, [zoomed, close]);

  return (
    <>
      <div ref={ref} className="xeos-article" dangerouslySetInnerHTML={{ __html: html }} />
      {zoomed && (
        <div className="xeos-lightbox" onClick={close} role="dialog" aria-modal="true" aria-label={zoomed.alt || 'Image'}>
          <button className="xeos-lightbox-close" onClick={close} aria-label="Close image"><X size={22} /></button>
          <figure onClick={(e) => e.stopPropagation()}>
            <img src={zoomed.src} alt={zoomed.alt} />
            {zoomed.caption && <figcaption>{zoomed.caption}</figcaption>}
          </figure>
        </div>
      )}
    </>
  );
}
