import { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import BlogLayout from '../components/BlogLayout';
import ArticleBody from '../components/ArticleBody';
import ArticleCard from '../components/ArticleCard';
import { findArticle, loadArticleBody, guides, posts } from '../content';

/**
 * Generic page for every article that comes from the content pack.
 * The body is fetched as its own chunk so a visit to one article never
 * downloads the other twenty.
 */
export default function Article({ type }) {
  const { slug } = useParams();
  const meta = findArticle(type, slug);
  const [html, setHtml] = useState(null);
  const [missing, setMissing] = useState(false);

  useEffect(() => {
    let live = true;
    setHtml(null);
    setMissing(false);
    loadArticleBody(type, slug)
      .then((body) => { if (!live) return; body ? setHtml(body) : setMissing(true); })
      .catch(() => { if (live) setMissing(true); });
    return () => { live = false; };
  }, [type, slug]);

  useEffect(() => {
    if (typeof window !== 'undefined') window.scrollTo(0, 0);
  }, [slug]);

  const related = (type === 'guide' ? guides : posts)
    .filter((a) => a.slug !== slug && a.card)
    .slice(0, 3);

  const title = meta?.title || 'Article';
  const description = meta?.description || '';

  return (
    <BlogLayout
      title={title}
      description={description}
      readTime={meta?.readTime || null}
      section={type === 'guide' ? 'guides' : 'blog'}
      tag={meta?.tag}
      jsonLd={meta ? {
        '@context': 'https://schema.org',
        '@type': 'Article',
        headline: title,
        description,
        image: meta.image ? `https://externaldisplayiphone.com${meta.image}` : undefined,
        author: { '@type': 'Organization', name: 'XeOS' },
        publisher: { '@type': 'Organization', name: 'XeOS: External Display Browser' },
        mainEntityOfPage: `https://externaldisplayiphone.com${meta.path}`,
      } : null}
    >
      {html ? (
        <ArticleBody html={html} />
      ) : missing ? (
        <p className="text-slate-600 dark:text-slate-300">
          This article could not be found.{' '}
          <a className="text-sky-600 dark:text-sky-400 hover:underline" href={type === 'guide' ? '/guides' : '/blog'}>
            See all {type === 'guide' ? 'guides' : 'articles'}
          </a>.
        </p>
      ) : (
        <div className="space-y-3 animate-pulse" aria-hidden="true">
          {[90, 100, 80, 95, 60].map((w, i) => (
            <div key={i} className="h-4 rounded bg-slate-200 dark:bg-slate-700" style={{ width: `${w}%` }} />
          ))}
        </div>
      )}

      {related.length > 0 && (
        <section className="mt-14 pt-10 border-t border-slate-200 dark:border-slate-700">
          <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-5">
            {type === 'guide' ? 'More guides' : 'More from the blog'}
          </h2>
          <div className="grid sm:grid-cols-3 gap-4">
            {related.map((a) => <ArticleCard key={a.slug} article={a} compact />)}
          </div>
        </section>
      )}
    </BlogLayout>
  );
}
