import { ArrowRight } from 'lucide-react';
import ArticleCard from './ArticleCard';
import { guides, posts } from '../content';

/**
 * Home-page teaser for the content pack: the three most useful guides and the
 * three lead articles. Both lists come from src/content/manifest.json, so a new
 * guide only has to be imported to show up here.
 */
